ALTER TABLE "DiagnosticFinding" ADD CONSTRAINT "DiagnosticFinding_targetId_fkey" FOREIGN KEY ("targetId") REFERENCES "DiagnosisTarget"("id") ON DELETE CASCADE ON UPDATE CASCADE;
